package com.careerpilot.backend.modules.discovery.services;
import io.micrometer.core.instrument.*; import org.springframework.stereotype.Component;
@Component public class DiscoveryMetrics { final Counter discovered,updated,duplicates,failures; final MeterRegistry registry; public DiscoveryMetrics(MeterRegistry r){registry=r;discovered=r.counter("careerpilot.discovery.jobs.discovered");updated=r.counter("careerpilot.discovery.jobs.updated");duplicates=r.counter("careerpilot.discovery.duplicates");failures=r.counter("careerpilot.discovery.connector.failures");} public Timer.Sample start(){return Timer.start(registry);} public void latency(Timer.Sample s,String id){s.stop(Timer.builder("careerpilot.discovery.connector.latency").tag("connector",id).register(registry));} public void duration(Timer.Sample s,String id){s.stop(Timer.builder("careerpilot.discovery.synchronization.duration").tag("connector",id).register(registry));} }
